            if (fn(line, data)) {
                total_processed++;
            }
        }
        fclose(file);
    }

    char user_config_path[256];
    char *home_dir = getenv("HOME");
    if (home_dir != NULL) {
        snprintf(user_config_path, sizeof(user_config_path), "%s/%s", home_dir, USER_CONFIG_PATH + 1);
